export async function refundPayment(event: { orderId: string; chargeId: string }) {
  const key = `refund:${event.orderId}`;
  if (await alreadyRefunded(key)) return { status: 'skipped' };
  await paymentApi.refund(event.chargeId, { idempotencyKey: key });
  await markRefunded(key);
  return { status: 'refunded' };
}
